create schema if not exists office_private;
revoke all on schema office_private from public, anon;
grant usage on schema office_private to authenticated;
create table office_private.allowed_admins(email text primary key);
alter table office_private.allowed_admins enable row level security;
create function office_private.is_admin() returns boolean language sql stable security definer set search_path = '' as $$
 select exists(select 1 from auth.users u join office_private.allowed_admins a on lower(u.email)=a.email where u.id=(select auth.uid()) and u.email_confirmed_at is not null);
$$;
revoke all on function office_private.is_admin() from public, anon;
grant execute on function office_private.is_admin() to authenticated;
create function public.office_access() returns boolean language sql stable security invoker set search_path = '' as $$ select office_private.is_admin(); $$;
revoke all on function public.office_access() from public, anon;
grant execute on function public.office_access() to authenticated;
create table public.office_records(kind text not null check(kind in ('customers','jobs','tasks','messages','company','compliance','employees','equipment','ledger','forms')), id text primary key, body jsonb not null, updated_at timestamptz not null default now());
create index office_records_kind_idx on public.office_records(kind);
create table public.office_audit(id uuid primary key default gen_random_uuid(), record_id text not null, body jsonb not null, created_at timestamptz not null default now());
create index office_audit_record_idx on public.office_audit(record_id);
create table public.office_documents(id uuid primary key, record_id text not null references public.office_records(id), name text not null, path text unique not null, created_at timestamptz not null default now());
create index office_documents_record_idx on public.office_documents(record_id);
create table public.office_packets(hash text primary key, path text unique not null, created_at timestamptz not null default now());
create table public.office_settings(id text primary key, body jsonb not null);
alter table public.office_records enable row level security;
revoke all on public.office_records from anon;
grant select, insert, update on public.office_records to authenticated;
create policy admin_read on public.office_records for select to authenticated using ((select office_private.is_admin()));
create policy admin_insert on public.office_records for insert to authenticated with check ((select office_private.is_admin()));
create policy admin_update on public.office_records for update to authenticated using ((select office_private.is_admin())) with check ((select office_private.is_admin()));
alter table public.office_audit enable row level security;
revoke all on public.office_audit from anon;
grant select, insert, update on public.office_audit to authenticated;
create policy admin_read on public.office_audit for select to authenticated using ((select office_private.is_admin()));
create policy admin_insert on public.office_audit for insert to authenticated with check ((select office_private.is_admin()));
alter table public.office_documents enable row level security;
revoke all on public.office_documents from anon;
grant select, insert, update on public.office_documents to authenticated;
create policy admin_read on public.office_documents for select to authenticated using ((select office_private.is_admin()));
create policy admin_insert on public.office_documents for insert to authenticated with check ((select office_private.is_admin()));
create policy admin_update on public.office_documents for update to authenticated using ((select office_private.is_admin())) with check ((select office_private.is_admin()));
alter table public.office_packets enable row level security;
revoke all on public.office_packets from anon;
grant select, insert, update on public.office_packets to authenticated;
create policy admin_read on public.office_packets for select to authenticated using ((select office_private.is_admin()));
create policy admin_insert on public.office_packets for insert to authenticated with check ((select office_private.is_admin()));
create policy admin_update on public.office_packets for update to authenticated using ((select office_private.is_admin())) with check ((select office_private.is_admin()));
alter table public.office_settings enable row level security;
revoke all on public.office_settings from anon;
grant select, insert, update on public.office_settings to authenticated;
create policy admin_read on public.office_settings for select to authenticated using ((select office_private.is_admin()));
create policy admin_insert on public.office_settings for insert to authenticated with check ((select office_private.is_admin()));
create policy admin_update on public.office_settings for update to authenticated using ((select office_private.is_admin())) with check ((select office_private.is_admin()));
create function public.office_save(p_kind text,p_id text,p_body jsonb,p_expected integer default null) returns jsonb language plpgsql security invoker set search_path = '' as $$
declare old_body jsonb; result jsonb; route text; title text; task_id text; task jsonb;
begin
 if not office_private.is_admin() then raise exception 'Administrator access required'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id,0));
 select body into old_body from public.office_records where id=p_id and kind=p_kind for update;
 if exists(select 1 from public.office_records where id=p_id and kind<>p_kind) then raise exception 'Record kind cannot change'; end if;
 if p_kind in ('forms','compliance') and old_body is not null and (p_expected is null or p_expected<>coalesce((old_body->>'version')::integer,0)) then raise exception 'This worksheet changed in another window. Refresh before saving.'; end if;
 result=p_body || jsonb_build_object('id',p_id,'updatedAt',to_char(now() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
 if p_kind in ('forms','compliance') then result=(result-'history') || jsonb_build_object('version',coalesce((old_body->>'version')::integer,0)+1); end if;
 insert into public.office_records(kind,id,body) values(p_kind,p_id,result) on conflict(id) do update set body=excluded.body,updated_at=now();
 insert into public.office_audit(record_id,body) values(p_id,jsonb_build_object('recordId',p_id,'kind',p_kind,'action',case when old_body is null then 'Record created' else 'Record updated' end,'at',result->>'updatedAt','before',old_body,'after',result));
 if p_kind='jobs' and (old_body->>'status') is distinct from (result->>'status') then
 route=case result->>'status' when 'Inquiry' then 'Customer Service' when 'Quoted' then 'Customer Service' when 'Scheduled' then 'Dispatch' when 'Dispatched' then 'Operations' when 'Delivered' then 'Finance' when 'Cancelled' then 'Customer Service' end;
 title=case result->>'status' when 'Inquiry' then 'Follow up on transport inquiry' when 'Quoted' then 'Confirm customer quote acceptance' when 'Scheduled' then 'Coordinate crew, vehicle, permits and route' when 'Dispatched' then 'Track move and collect delivery acceptance' when 'Delivered' then 'Reconcile income, expenses and final balance' when 'Cancelled' then 'Confirm cancellation and any refund review' end;
 elsif p_kind='compliance' and result->>'status' in ('In progress','Waiting on agency') and (old_body->>'status') is distinct from (result->>'status') then route='Compliance';title='Follow up: '||(result->>'title');
 elsif p_kind='equipment' and coalesce(result->>'status','') ~* 'repair|needed' and (old_body->>'status') is distinct from (result->>'status') then route='Fleet';title='Review repairs / needed items: '||(result->>'name');
 elsif p_kind='ledger' and old_body is null then route='Finance';title='Review '||lower(result->>'type')||': '||(result->>'description'); end if;
 if route is not null then
 task_id=gen_random_uuid()::text;task=jsonb_build_object('id',task_id,'title',title,'department',route,'sourceId',p_id,'sourceKind',p_kind,'jobId',case when p_kind='jobs' then p_id else coalesce(result->>'jobId','') end,'priority','Normal','done',false,'due',case when p_kind='jobs' then coalesce(result->>'date','') else '' end,'notes','Automatically routed. Review and assign an employee.','updatedAt',result->>'updatedAt');
 insert into public.office_records(kind,id,body) values('tasks',task_id,task);
 insert into public.office_audit(record_id,body) values(task_id,jsonb_build_object('recordId',task_id,'action','Department handoff','department',route,'at',result->>'updatedAt','after',task));
 end if;
 return result;
end;$$;
revoke all on function public.office_save(text,text,jsonb,integer) from public, anon;
grant execute on function public.office_save(text,text,jsonb,integer) to authenticated;
insert into storage.buckets(id,name,public,file_size_limit) values('office-documents','office-documents',false,10000000);
create policy office_storage_read on storage.objects for select to authenticated using(bucket_id='office-documents' and (select office_private.is_admin()));
create policy office_storage_insert on storage.objects for insert to authenticated with check(bucket_id='office-documents' and (select office_private.is_admin()));
